// src/pages/MeetingRoom.js

import {
  useLocation,
} from "react-router-dom";

import {
  useState,
  useEffect,
  useRef,
} from "react";

function MeetingRoom() {
  const location = useLocation();

  const roomTitle =
    location.state?.title ||
    "독서모임";

  const badgeClass =
    location.state?.mood || "badge1";

  const [input, setInput] =
    useState("");

  const [messages, setMessages] =
    useState([
      {
        user: "AI",
        type: "ai",
        text:
          "모임원들이 기록한 감상을 먼저 정리해봤어요 ✨\n\n• 외로움과 연결감\n• 상실 이후의 성장\n• 사람 사이의 거리감\n• 잔잔하지만 깊은 감정선",
      },

      {
        user: "AI",
        type: "ai",
        text:
          "안녕하세요 🙂 오늘은 가장 인상 깊었던 장면을 이야기해볼게요.",
      },

      {
        user: "민지",
        type: "other",
        color: "#FFB6C1",
        text:
          "저는 마지막 장면이 가장 슬펐어요.",
      },

      {
        user: "현우",
        type: "other",
        color: "#87CEEB",
        text:
          "와타나베의 감정선이 정말 좋았어요.",
      },

      {
        user: "서연",
        type: "other",
        color: "#C3E88D",
        text:
          "문장이 되게 고요한 느낌이라 좋았어요.",
      },
    ]);

  const chatEndRef = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({
      behavior: "smooth",
    });
  }, [messages]);

  const sendMessage = () => {
    if (!input.trim()) return;

    const newMessage = {
      user: "나",
      type: "me",
      text: input,
    };

    setMessages([
      ...messages,
      newMessage,
    ]);

    setInput("");

    setTimeout(() => {
      setMessages((prev) => [
        ...prev,
        {
          user: "AI",
          type: "ai",
          text:
            "좋은 의견이네요 🌿 조금 더 자세히 이야기해볼까요?",
        },
      ]);
    }, 1000);
  };

  return (
    <div className="meeting-page">
      {/* 상단 */}

      <div className="meeting-header">
        <div>
          <div className="meeting-room-name">
            📚 {roomTitle}
          </div>

          <div className={badgeClass}>
            {badgeClass ===
              "badge1" &&
              "깊게 토론해요"}

            {badgeClass ===
              "badge2" &&
              "부담없이 참여해요"}

            {badgeClass ===
              "badge3" &&
              "함께 이야기해요"}
          </div>
        </div>
      </div>

      {/* 채팅 */}

      <div className="meeting-chat-area">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`chat-row ${
              msg.type === "me"
                ? "right"
                : "left"
            }`}
          >
            {msg.type !== "me" && (
              <div
                className="chat-profile"
                style={{
                  background:
                    msg.type === "ai"
                      ? "#9bd44e"
                      : msg.color,
                }}
              >
                {msg.user[0]}
              </div>
            )}

            <div className="chat-content">
              {msg.type !== "me" && (
                <div className="chat-name">
                  {msg.user}
                </div>
              )}

              <div
                className={`chat-bubble ${
                  msg.type === "me"
                    ? "user-chat"
                    : msg.type ===
                      "ai"
                    ? "ai-chat"
                    : "other-chat"
                }`}
              >
                {msg.text}
              </div>
            </div>
          </div>
        ))}

        <div ref={chatEndRef}></div>
      </div>

      {/* 입력창 */}

      <div className="meeting-input-wrap">
        <input
          value={input}
          onChange={(e) =>
            setInput(e.target.value)
          }
          placeholder="생각을 입력해보세요"
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              sendMessage();
            }
          }}
        />

        <button onClick={sendMessage}>
          전송
        </button>
      </div>
    </div>
  );
}

export default MeetingRoom;
